//! Unicode properties for the terminal: display width and grapheme cluster
//! boundaries (UAX #29), from tables generated by `cargo xtask gen-unicode`.

#[allow(clippy::all)]
mod tables;

pub use tables::UNICODE_VERSION;

/// Grapheme_Cluster_Break property.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum Gcb {
    Other = 0,
    Cr,
    Lf,
    Control,
    Extend,
    Zwj,
    RegionalIndicator,
    Prepend,
    SpacingMark,
    L,
    V,
    T,
    Lv,
    Lvt,
}

/// Indic_Conjunct_Break property.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InCb {
    None,
    Consonant,
    Extend,
    Linker,
}

/// Packed properties of one code point.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Props(u16);

impl Props {
    pub fn of(c: char) -> Props {
        let cp = c as u32;
        let block = tables::STAGE1[(cp >> tables::BLOCK_SHIFT) as usize] as usize;
        Props(tables::STAGE2[(block << tables::BLOCK_SHIFT) | (cp as usize & 0xff)])
    }

    /// Display width in cells: 0, 1 or 2.
    pub fn width(self) -> u8 {
        (self.0 & 0b11) as u8
    }

    pub fn gcb(self) -> Gcb {
        const ALL: [Gcb; 14] = [
            Gcb::Other,
            Gcb::Cr,
            Gcb::Lf,
            Gcb::Control,
            Gcb::Extend,
            Gcb::Zwj,
            Gcb::RegionalIndicator,
            Gcb::Prepend,
            Gcb::SpacingMark,
            Gcb::L,
            Gcb::V,
            Gcb::T,
            Gcb::Lv,
            Gcb::Lvt,
        ];
        ALL.get(((self.0 >> 2) & 0xf) as usize).copied().unwrap_or(Gcb::Other)
    }

    pub fn extended_pictographic(self) -> bool {
        self.0 & (1 << 6) != 0
    }

    pub fn incb(self) -> InCb {
        match (self.0 >> 7) & 0b11 {
            1 => InCb::Consonant,
            2 => InCb::Extend,
            3 => InCb::Linker,
            _ => InCb::None,
        }
    }
}

impl std::fmt::Debug for Props {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "w{} {:?} pict={} {:?}", self.width(), self.gcb(), self.extended_pictographic(), self.incb())
    }
}

/// Display width of a single code point (0, 1 or 2).
pub fn width(c: char) -> u8 {
    // ASCII fast path.
    match c as u32 {
        0x20..=0x7e => 1,
        0..=0x1f | 0x7f => 0,
        _ => Props::of(c).width(),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum EmojiState {
    #[default]
    None,
    /// Extended_Pictographic Extend*
    Pict,
    /// Extended_Pictographic Extend* ZWJ
    PictZwj,
}

/// Incremental grapheme cluster boundary detection (UAX #29, extended
/// grapheme clusters).
#[derive(Debug, Clone, Default)]
pub struct GraphemeBreaker {
    prev: Option<Props>,
    emoji: EmojiState,
    /// GB9c: a Linker followed only by Extend/Linker precedes the current
    /// position (Unicode 18 no longer requires a Consonant before it).
    linked: bool,
    /// An odd number of Regional_Indicators precede the current position.
    ri_odd: bool,
}

impl GraphemeBreaker {
    pub fn new() -> GraphemeBreaker {
        GraphemeBreaker::default()
    }

    /// Forget context (e.g. after the cursor moved).
    pub fn reset(&mut self) {
        *self = GraphemeBreaker::default();
    }

    /// Feed the next character; returns `true` if a cluster boundary falls
    /// before it.
    pub fn push(&mut self, c: char) -> bool {
        self.push_props(Props::of(c))
    }

    /// [`push`](Self::push) with the character's properties already looked up.
    pub fn push_props(&mut self, next: Props) -> bool {
        let brk = match self.prev {
            None => true, // GB1
            Some(prev) => self.is_break(prev, next),
        };
        self.update(next);
        brk
    }

    fn is_break(&self, prev: Props, next: Props) -> bool {
        use Gcb::*;
        let (p, n) = (prev.gcb(), next.gcb());
        match (p, n) {
            (Cr, Lf) => false,                                                               // GB3
            (Control | Cr | Lf, _) | (_, Control | Cr | Lf) => true,                         // GB4, GB5
            (L, L | V | Lv | Lvt) => false,                                                  // GB6
            (Lv | V, V | T) => false,                                                        // GB7
            (Lvt | T, T) => false,                                                           // GB8
            (_, Extend | Zwj) => false,                                                      // GB9
            (_, SpacingMark) => false,                                                       // GB9a
            (Prepend, _) => false,                                                           // GB9b
            _ if self.linked && next.incb() == InCb::Consonant => false,                     // GB9c
            _ if self.emoji == EmojiState::PictZwj && next.extended_pictographic() => false, // GB11
            (RegionalIndicator, RegionalIndicator) => !self.ri_odd,                          // GB12, GB13
            _ => true,                                                                       // GB999
        }
    }

    fn update(&mut self, next: Props) {
        self.emoji = if next.extended_pictographic() {
            EmojiState::Pict
        } else {
            match (self.emoji, next.gcb()) {
                (EmojiState::Pict, Gcb::Extend) => EmojiState::Pict,
                (EmojiState::Pict, Gcb::Zwj) => EmojiState::PictZwj,
                _ => EmojiState::None,
            }
        };
        self.linked = match next.incb() {
            InCb::Linker => true,
            InCb::Extend => self.linked,
            _ => false,
        };
        self.ri_odd = next.gcb() == Gcb::RegionalIndicator && !self.ri_odd;
        self.prev = Some(next);
    }
}

/// Display width of a whole grapheme cluster: the first character's width,
/// widened to 2 by VS16 (emoji presentation) or a regional-indicator pair.
pub fn cluster_width(cluster: &str) -> u8 {
    let mut chars = cluster.chars();
    let Some(first) = chars.next() else { return 0 };
    let base = width(first);
    let rest = chars.as_str();
    if base == 1 && (rest.contains('\u{fe0f}') || Props::of(first).gcb() == Gcb::RegionalIndicator && !rest.is_empty())
    {
        return 2;
    }
    base
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn widths() {
        assert_eq!(width('a'), 1);
        assert_eq!(width('\u{0}'), 0);
        assert_eq!(width('é'), 1);
        assert_eq!(width('\u{301}'), 0, "combining acute");
        assert_eq!(width('漢'), 2);
        assert_eq!(width('ｱ'), 1, "halfwidth katakana");
        assert_eq!(width('Ａ'), 2, "fullwidth A");
        assert_eq!(width('🙂'), 2);
        assert_eq!(width('\u{200b}'), 0, "zero width space");
        assert_eq!(width('\u{ad}'), 1, "soft hyphen is visible");
        assert_eq!(width('\u{1160}'), 0, "hangul medial vowel");
        assert_eq!(width('\u{3fffd}'), 2, "unassigned CJK plane defaults to wide");
        assert_eq!(width('✓'), 1);
    }

    #[test]
    fn cluster_widths() {
        assert_eq!(cluster_width("❤\u{fe0f}"), 2, "VS16 widens");
        assert_eq!(cluster_width("🇬🇧"), 2, "flag");
        assert_eq!(cluster_width("e\u{301}"), 1);
        assert_eq!(cluster_width("👩\u{200d}💻"), 2);
    }

    /// Every case in the official GraphemeBreakTest.txt.
    #[test]
    fn grapheme_break_test_file() {
        let src = include_str!("../../../data/unicode/GraphemeBreakTest.txt");
        let mut cases = 0;
        let mut failures = Vec::new();
        for line in src.lines() {
            let body = line.split('#').next().unwrap().trim();
            if body.is_empty() {
                continue;
            }
            // "÷ 0020 × 0308 ÷": chars with the expected boundary before each.
            let mut chars = Vec::new();
            let mut expect = Vec::new();
            let mut pending = None;
            for tok in body.split_whitespace() {
                match tok {
                    "÷" => pending = Some(true),
                    "×" => pending = Some(false),
                    hex => {
                        chars.push(char::from_u32(u32::from_str_radix(hex, 16).unwrap()).unwrap());
                        expect.push(pending.take().unwrap());
                    }
                }
            }
            let mut b = GraphemeBreaker::new();
            let got: Vec<bool> = chars.iter().map(|&c| b.push(c)).collect();
            cases += 1;
            if got != expect {
                failures.push(format!("{line}\n    got {got:?}"));
            }
        }
        assert!(cases > 500, "only {cases} cases parsed");
        assert!(
            failures.is_empty(),
            "{} of {cases} failed:\n{}",
            failures.len(),
            failures[..failures.len().min(10)].join("\n")
        );
    }
}
